-- Phase 59: Operational Incident Management. Extends canonical support, security, maintenance, quality, tasks, notifications and automation.
-- quality: allow-nonconcurrent-index reason=new-empty-phase59-tables
alter table public.plans add column if not exists incident_management_enabled boolean not null default true;
alter table public.plans add column if not exists incident_war_room_enabled boolean not null default true;
alter table public.plans add column if not exists incident_detection_enabled boolean not null default true;
alter table public.plans add column if not exists incident_postmortems_enabled boolean not null default true;
alter table public.plans add column if not exists network_incidents_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists incident_management_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists incident_war_room_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists incident_detection_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists incident_postmortems_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists network_incidents_enabled boolean not null default true;

create table public.incident_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{incidents:view}',scope_type text not null default 'organization' check(scope_type in('organization','brand','region','cluster','store')),scope_id uuid,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create unique index incident_member_permissions_scope_idx on public.incident_member_permissions(organization_id,user_id,scope_type,coalesce(scope_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table public.incident_severity_criteria(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,severity text not null check(severity in('SEV1','SEV2','SEV3','SEV4')),criteria jsonb not null,priority integer not null default 100,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_response_targets(organization_id uuid not null references public.organizations(id) on delete cascade,severity text not null check(severity in('SEV1','SEV2','SEV3','SEV4')),acknowledge_target_minutes integer not null check(acknowledge_target_minutes>0),containment_target_minutes integer not null check(containment_target_minutes>0),update_frequency_minutes integer not null check(update_frequency_minutes>0),postmortem_required boolean not null default false,close_review_required boolean not null default false,escalation_chain jsonb not null default '[]',primary key(organization_id,severity));

create table public.operational_incidents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,
 incident_number text not null,title text not null,summary text not null,category text not null check(category in('system','payments','hardware','network','kitchen','delivery','inventory','supplier','quality','maintenance','security','workforce','store_operations','integration','release','other')),
 severity text not null check(severity in('SEV1','SEV2','SEV3','SEV4')),severity_score numeric(6,2),severity_reason text,manual_severity_override boolean not null default false,
 status text not null default 'detected' check(status in('detected','investigating','acknowledged','contained','monitoring','resolved','closed','cancelled')),
 visibility text not null default 'operational' check(visibility in('operational','restricted','confidential')),source_type text not null,source_id text,idempotency_key text,
 owner_user_id uuid references auth.users(id),commander_user_id uuid references auth.users(id),detected_at timestamptz not null default now(),started_at timestamptz,acknowledged_at timestamptz,contained_at timestamptz,resolved_at timestamptz,closed_at timestamptz,
 resolution_summary text,resolved_by uuid references auth.users(id),resolution_type text check(resolution_type is null or resolution_type in('fixed','mitigated','provider_recovered','workaround','false_positive','duplicate','cancelled')),
 duplicate_of_id uuid references public.operational_incidents(id) on delete set null,merged_into_id uuid references public.operational_incidents(id) on delete set null,offline_client_id uuid,client_detected_at timestamptz,server_received_at timestamptz not null default now(),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,incident_number),unique(organization_id,idempotency_key),check(severity<>'SEV1' or owner_user_id is not null)
);
create unique index operational_incidents_active_source_idx on public.operational_incidents(organization_id,source_type,source_id,category) where source_id is not null and status not in('closed','cancelled');
create index operational_incidents_board_idx on public.operational_incidents(organization_id,status,severity,detected_at desc);
create index operational_incidents_store_idx on public.operational_incidents(organization_id,store_id,status,detected_at desc);

create table public.incident_scopes(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','cluster','store','service','provider')),scope_id text not null,created_at timestamptz not null default now(),unique(incident_id,scope_type,scope_id));
create table public.incident_impacts(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,impact_type text not null check(impact_type in('store_unavailable','payments_unavailable','kitchen_degraded','delivery_degraded','orders_delayed','inventory_blocked','customers_affected','revenue_estimate','hardware_unavailable','other')),entity_type text,entity_id text,estimated_value numeric(18,2),unit text,start_at timestamptz not null,end_at timestamptz,notes text,is_estimate boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(end_at is null or end_at>=start_at));
create table public.incident_responders(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('commander','operations','technical','communications','finance','store_manager','observer','custom')),custom_role text,joined_at timestamptz not null default now(),left_at timestamptz,added_by uuid references auth.users(id),unique(incident_id,user_id,role));
create table public.incident_war_rooms(id uuid primary key default gen_random_uuid(),incident_id uuid not null unique references public.operational_incidents(id) on delete cascade,status text not null default 'active' check(status in('active','monitoring','archived')),next_update_due_at timestamptz,summary text,links jsonb not null default '[]',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_timeline_events(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,event_type text not null check(event_type in('detected','acknowledged','severity_changed','responder_added','investigation_update','containment_action','communication_sent','status_changed','recovery_step','resolved','closed','note','correction','merged','split')),event_time timestamptz not null,server_received_at timestamptz not null default now(),actor_user_id uuid references auth.users(id),source_type text not null,source_id text,summary text not null,details jsonb,visibility text not null default 'operational' check(visibility in('operational','restricted','confidential')),corrects_event_id uuid references public.incident_timeline_events(id) on delete restrict,created_at timestamptz not null default now());
create index incident_timeline_cursor_idx on public.incident_timeline_events(incident_id,event_time desc,id desc);

create table public.incident_runbooks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,category text not null,severity_scope text[] not null default '{SEV1,SEV2,SEV3,SEV4}',owner_user_id uuid references auth.users(id),version integer not null default 1,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name,version));
create table public.incident_runbook_steps(id uuid primary key default gen_random_uuid(),runbook_id uuid not null references public.incident_runbooks(id) on delete cascade,step_order integer not null,step_type text not null check(step_type in('check','task','communication','action','decision')),title text not null,instructions text,action_type text,requires_confirmation boolean not null default true,validation_schema jsonb not null default '{}',unique(runbook_id,step_order));
create table public.incident_runbook_executions(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,runbook_id uuid not null references public.incident_runbooks(id),runbook_version integer not null,status text not null default 'active' check(status in('active','paused','completed','cancelled')),step_states jsonb not null default '[]',started_by uuid not null references auth.users(id),started_at timestamptz not null default now(),completed_at timestamptz);
create table public.incident_task_links(incident_id uuid not null references public.operational_incidents(id) on delete cascade,task_id uuid not null references public.internal_tasks(id) on delete cascade,link_type text not null default 'response' check(link_type in('response','corrective','preventive','follow_up','communication_draft')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),primary key(incident_id,task_id));
create table public.incident_containment_actions(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,action_type text not null,description text not null,status text not null default 'proposed' check(status in('proposed','awaiting_approval','in_progress','completed','failed','cancelled')),action_request_id uuid references public.copilot_action_requests(id) on delete set null,requires_action_engine boolean not null default true,requested_by uuid references auth.users(id),confirmed_by uuid references auth.users(id),started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.incident_recovery_steps(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,description text not null,owner_user_id uuid references auth.users(id),step_order integer not null,status text not null default 'pending' check(status in('pending','in_progress','completed','failed','skipped')),started_at timestamptz,completed_at timestamptz,validation_required boolean not null default true,validated_by uuid references auth.users(id),validated_at timestamptz,rollout_percent integer check(rollout_percent between 0 and 100),created_at timestamptz not null default now(),unique(incident_id,step_order));
create table public.incident_postmortems(id uuid primary key default gen_random_uuid(),incident_id uuid not null unique references public.operational_incidents(id) on delete cascade,summary text,customer_impact text,operational_impact text,what_happened text,timeline_summary text,root_cause_status text not null default 'unknown' check(root_cause_status in('unknown','suspected','confirmed')),root_cause_description text,contributing_factors jsonb not null default '[]',what_went_well jsonb not null default '[]',what_went_wrong jsonb not null default '[]',action_items jsonb not null default '[]',reviewed_by uuid references auth.users(id),human_reviewed boolean not null default false,follow_up_deadline date,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(root_cause_status<>'confirmed' or (human_reviewed and nullif(trim(root_cause_description),'') is not null)));

create table public.incident_relations(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.operational_incidents(id) on delete cascade,relation_type text not null check(relation_type in('source','related','caused_by','affected','duplicate','merged','split','communication')),entity_type text not null,entity_id text not null,visibility text not null default 'operational' check(visibility in('operational','restricted','confidential')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(incident_id,relation_type,entity_type,entity_id));
create table public.incident_detection_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,name text not null,source_type text not null,metric_or_event text not null,operator text not null check(operator in('gt','gte','lt','lte','eq','count')),threshold numeric not null,duration_seconds integer not null check(duration_seconds>=30),hysteresis numeric,category text not null,default_severity text not null check(default_severity in('SEV1','SEV2','SEV3','SEV4')),auto_create boolean not null default false,active boolean not null default true,cooldown_seconds integer not null default 1800,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_candidates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,detection_rule_id uuid references public.incident_detection_rules(id) on delete set null,source_type text not null,source_id text,category text not null,suggested_severity text not null check(suggested_severity in('SEV1','SEV2','SEV3','SEV4')),title text not null,evidence jsonb not null,status text not null default 'pending' check(status in('pending','confirmed','dismissed','expired','auto_created')),incident_id uuid references public.operational_incidents(id) on delete set null,detected_at timestamptz not null,expires_at timestamptz,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.known_operational_issues(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,title text not null,pattern jsonb not null,workaround text,status text not null default 'known' check(status in('known','monitoring','resolved','archived')),runbook_id uuid references public.incident_runbooks(id) on delete set null,linked_incident_ids uuid[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incident_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,incident_id uuid references public.operational_incidents(id) on delete set null,actor_user_id uuid references auth.users(id),action text not null,reason text,before_state jsonb,after_state jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
create table public.incident_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,incident_id uuid references public.operational_incidents(id) on delete cascade,job_type text not null check(job_type in('correlation','impact_refresh','escalation','notification','analytics')),payload_redacted jsonb not null default '{}',status text not null default 'pending' check(status in('pending','leased','completed','failed','dead_lettered')),priority integer not null default 50,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),leased_until timestamptz,worker_id text,last_error text,completed_at timestamptz,created_at timestamptz not null default now());

create table public.fact_operational_incidents(organization_id uuid not null,store_id uuid,incident_id uuid not null,category text not null,severity text not null,status text not null,detected_at timestamptz not null,resolved_at timestamptz,closed_at timestamptz,data_as_of timestamptz not null,primary key(organization_id,incident_id));
create table public.fact_incident_impacts(organization_id uuid not null,incident_id uuid not null,impact_type text not null,estimated_value numeric,unit text,data_as_of timestamptz not null,primary key(organization_id,incident_id,impact_type,unit));
create table public.fact_incident_timeline_events(organization_id uuid not null,incident_id uuid not null,event_type text not null,event_count bigint not null,last_event_at timestamptz not null,data_as_of timestamptz not null,primary key(organization_id,incident_id,event_type));
create table public.fact_incident_response_times(organization_id uuid not null,incident_id uuid not null,mttd_seconds bigint,mtta_seconds bigint,mttc_seconds bigint,mttr_recovery_seconds bigint,data_as_of timestamptz not null,primary key(organization_id,incident_id));
create table public.fact_incident_recovery(organization_id uuid not null,incident_id uuid not null,total_steps integer not null,completed_steps integer not null,validated_steps integer not null,data_as_of timestamptz not null,primary key(organization_id,incident_id));
create table public.fact_incident_postmortems(organization_id uuid not null,incident_id uuid not null,required boolean not null,completed boolean not null,root_cause_status text not null,data_as_of timestamptz not null,primary key(organization_id,incident_id));
