('Incidentes por Categoria','Volume por categoria.','operations','operational_incidents','{"type":"grouped_table","groupBy":["category"]}',true,true,'{reports:view,incidents:view_analytics}',true),('MTTA e MTTR','Reconhecimento e recuperação.','operations','operational_incidents','{"type":"trend","metrics":["mean_time_to_acknowledge","mean_time_to_recover"]}',true,true,'{reports:view,incidents:view_analytics}',true),('Incidentes por Unidade','Incidentes e impacto por unidade.','operations','operational_incidents','{"type":"grouped_table","groupBy":["store"]}',true,true,'{reports:view,incidents:view_analytics}',true),('Incidentes Recorrentes','Sinais recorrentes sem inferir mesma causa.','operations','operational_incidents','{"type":"table","metrics":["incident_recurrence_rate"]}',true,true,'{reports:view,incidents:view_analytics}',false),('Postmortems Pendentes','Revisões obrigatórias pendentes.','operations','operational_incidents','{"type":"table","metrics":["postmortem_completion_rate"]}',true,true,'{reports:view,incidents:view_analytics}',true);
alter table public.search_documents drop constraint if exists search_documents_entity_type_check;
alter table public.search_documents add constraint search_documents_entity_type_check check(entity_type in('order','customer','product','category','table','tab','reservation','delivery','driver','employee','supplier','purchase_order','inventory_item','lot','asset','maintenance_work_order','contract','document','support_ticket','internal_project','internal_task','sales_opportunity','organization','store','campaign','workflow','configuration','report','user','operational_incident'));

do $$ declare t text;begin foreach t in array array['incident_member_permissions','incident_severity_criteria','incident_response_targets','operational_incidents','incident_scopes','incident_impacts','incident_responders','incident_war_rooms','incident_timeline_events','incident_runbooks','incident_runbook_steps','incident_runbook_executions','incident_task_links','incident_containment_actions','incident_recovery_steps','incident_postmortems','incident_relations','incident_detection_rules','incident_candidates','known_operational_issues','incident_audit_events','incident_jobs','fact_operational_incidents','fact_incident_impacts','fact_incident_timeline_events','fact_incident_response_times','fact_incident_recovery','fact_incident_postmortems','dim_incident_category','dim_incident_severity','dim_incident_status','dim_incident_source'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',left(t||'_service_only',63),t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
comment on table public.operational_incidents is 'Phase 59 operational incidents. Security, support, maintenance and quality remain canonical linked sources.';
comment on table public.incident_postmortems is 'Blameless review; AI drafts never confirm root cause and human review is mandatory for confirmed RCA.';
